#!/usr/bin/env python3
"""V5 güvenlik ve düzeltme paketi — tek seferlik. damga iş akışı çalıştırır, sonra siler.
Her dosya ancak beklenen (main @ 624045e) içerikteyse değiştirilir; biri farklıysa HİÇBİR dosyaya
dokunmadan durur. Böylece başka oturumun yaptığı değişikliğin üzerine yazılmaz."""
import hashlib, os, sys, zlib, base64
KOK = sys.argv[1] if len(sys.argv) > 1 else '.'
PAKET = [
  ('.github/damgala.py', 'a93bbf273118b5817efef6a6bee5ca3f',
   ''),
  ('_worker.js', 'c0f8e61cecc2b617c4bb360d3d8517f5',
   ''),
  ('araclar/civata-germe/index.html', '716e976f928783e2afe28bc6d2d6071b',
   ''),
  ('assets/bilgi-tr.json', '1eca8664aa32dd85a7192d41640c924c',
   ''),
  ('deneyim/index.html', '684e5dacdd8de17b7e1910de539dff09',
   ''),
  ('en/ad-policy/index.html', '4eb72c5e03ad7b6c89d47ba65872148f',
   ''),
  ('en/diagnostics/index.html', 'd82b2a6eefbac8afcfc4b1455a987349',
   ''),
  ('en/gwo/index.html', '1e3f1ed8912ad9b3e29657bbcd919f4f',
   ''),
  ('en/how-to-become/index.html', '56c0a068fe0f2424919ef4a24fb6b335',
   ''),
  ('en/pay/index.html', 'b2f2e7b5d4067e11974d18f7f076ba95',
   ''),
  ('en/privacy/index.html', '51ce5c93aed3b594c8f530f97d1327e6',
   ''),
  ('gelir/index.html', 'a51289fcfc280f3f677a41e903f6bd0e',
   ''),
  ('gizlilik/index.html', 'ca30d66f27076faabf0c8bc8e842626e',
   ''),
  ('iletisim/index.html', '3d1ee4a9b7689c45bd5b3d0517dd5609',
   ''),
  ('manifest.webmanifest', '314a6399f530402e916bb9643e1d8007',
   ''),
  ('saha-notlari/jenerator-sicaklik/index.html', '869f00d712934282fb5d1b27b7db6a3c',
   ''),
  ('teshis/index.html', '6bd77ad1be30e941462cfb7e72233fef',
   ''),
  ('veri/index.html', '44f832660708afa09e4f8ea48a1b6b1e',
   '')
]
for yol, beklenen, _ in PAKET:
    p = os.path.join(KOK, yol)
    gercek = hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.isfile(p) else 'yok'
    if gercek != beklenen:
        sys.exit('DURDU: ' + yol + ' beklenenden farklı (' + gercek + '). Hiçbir dosya değiştirilmedi.')
for yol, _, veri in PAKET:
    open(os.path.join(KOK, yol), 'wb').write(zlib.decompress(base64.b64decode(veri)))
    print('güncellendi:', yol)
